html[data-slaidy-theme="fit-cvut"]{--th-paper:#FFFFFF;--th-ink:#111827;--th-text:#272C33;--th-muted:#6B7280;
 --th-line:#DCE3EB;--th-blue:#0065BD;--th-light:#6CACE4;--th-wash:#EEF5FB;--th-font:"Titillium Web",system-ui,sans-serif}

/* ---------- content slides: white, the title in CTU blue, the logo bottom right ---------- */
html[data-slaidy-theme="fit-cvut"] .stage{background:var(--th-paper);color:var(--th-ink);padding:44px 72px 84px;
 font-family:var(--th-font);-webkit-print-color-adjust:exact;print-color-adjust:exact}
html[data-slaidy-theme="fit-cvut"] .stage h2{font-family:var(--th-font);font-weight:700;color:var(--th-blue);
 letter-spacing:-.005em;line-height:1.1;margin-bottom:20px}
html[data-slaidy-theme="fit-cvut"] .stage .tx{font-family:var(--th-font);font-weight:400;color:var(--th-text);line-height:1.42}
html[data-slaidy-theme="fit-cvut"] .stage .tx b,html[data-slaidy-theme="fit-cvut"] .stage .tx strong{font-weight:700;color:var(--th-ink)}
html[data-slaidy-theme="fit-cvut"] .stage .tx em{color:var(--th-blue)}
html[data-slaidy-theme="fit-cvut"] .stage .tx li::marker{color:var(--th-blue)}
html[data-slaidy-theme="fit-cvut"] .stage .tx .bh{font-family:var(--th-font);color:var(--th-ink)}
html[data-slaidy-theme="fit-cvut"] .stage .tx h4.bh{font-weight:600;color:var(--th-blue);letter-spacing:.08em;
 text-transform:uppercase;font-size:.72em}
html[data-slaidy-theme="fit-cvut"] .stage .tx blockquote{border-left:4px solid var(--th-blue);background:none;
 padding:.1em 0 .1em .9em;margin:.6em 0;font-weight:600;color:var(--th-ink)}
html[data-slaidy-theme="fit-cvut"] .stage .tx a{color:var(--th-blue);text-decoration:underline;text-underline-offset:3px}
html[data-slaidy-theme="fit-cvut"] .stage .tx code{background:var(--th-wash);color:var(--th-ink);border:0;border-radius:3px;padding:.06em .3em}
html[data-slaidy-theme="fit-cvut"] .stage .tx pre{background:var(--th-wash);border:0;border-left:3px solid var(--th-light);border-radius:0}
html[data-slaidy-theme="fit-cvut"] .stage .tx pre code{background:none;padding:0}
html[data-slaidy-theme="fit-cvut"] .stage .tx table{border-collapse:collapse;font-size:.9em}
html[data-slaidy-theme="fit-cvut"] .stage .tx th{font-weight:700;color:var(--th-blue);border:0;border-bottom:2px solid var(--th-blue)}
html[data-slaidy-theme="fit-cvut"] .stage .tx td{border:0;border-bottom:1px solid var(--th-line)}
html[data-slaidy-theme="fit-cvut"] .stage .tx .rule{border-top:1px solid var(--th-line)}
html[data-slaidy-theme="fit-cvut"] .stage .hdr{color:var(--th-muted);font-family:var(--th-font);font-weight:600;letter-spacing:.1em}
html[data-slaidy-theme="fit-cvut"] .stage .hdr .ix,html[data-slaidy-theme="fit-cvut"] .stage .pos{color:var(--th-muted)}
html[data-slaidy-theme="fit-cvut"] .stage::before{content:"";position:absolute;right:64px;bottom:22px;width:118px;height:38px;
 background:url(data:image/svg+xml;base64,) no-repeat right center/contain;z-index:2}
html[data-slaidy-theme="fit-cvut"] .stage::after{content:var(--slaidy-footer,"");position:absolute;left:72px;right:220px;bottom:30px;
 font:400 14px/1.2 var(--th-font);color:var(--th-muted);letter-spacing:.02em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

/* ---------- cover & closing: the full logo top left, a big blue title, a light-blue rule ---------- */
html[data-slaidy-theme="fit-cvut"] .stage.lay-cover,html[data-slaidy-theme="fit-cvut"] .stage.lay-closing{padding:212px 112px 96px}
html[data-slaidy-theme="fit-cvut"] .stage.lay-cover::before,html[data-slaidy-theme="fit-cvut"] .stage.lay-closing::before{
 left:104px;top:60px;right:auto;bottom:auto;width:300px;height:98px;background-position:left center}
html[data-slaidy-theme="fit-cvut"] .stage.lay-cover::after,html[data-slaidy-theme="fit-cvut"] .stage.lay-closing::after{
 content:"";left:0;right:0;bottom:0;height:10px;background:var(--th-blue)}
html[data-slaidy-theme="fit-cvut"] .stage.lay-cover h2,html[data-slaidy-theme="fit-cvut"] .stage.lay-closing h2{max-width:84%;letter-spacing:-.015em}
html[data-slaidy-theme="fit-cvut"] .stage.lay-cover h2.big{font-size:calc(var(--d-title)*1.5)}
html[data-slaidy-theme="fit-cvut"] .stage.lay-closing h2.big{font-size:calc(var(--d-title)*1.3)}
html[data-slaidy-theme="fit-cvut"] .stage.lay-cover h2::after,html[data-slaidy-theme="fit-cvut"] .stage.lay-closing h2::after{
 content:"";display:block;width:96px;height:5px;margin-top:22px;background:var(--th-light)}
html[data-slaidy-theme="fit-cvut"] .stage.lay-cover .tx p,html[data-slaidy-theme="fit-cvut"] .stage.lay-cover .tx ul,
html[data-slaidy-theme="fit-cvut"] .stage.lay-closing .tx p,html[data-slaidy-theme="fit-cvut"] .stage.lay-closing .tx ul{max-width:70%}
